import { Group, Mesh, PlaneGeometry, Color, DoubleSide } from 'three/webgpu';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

/**
 * @typedef {object} NodeConfig
 * @property {any} [textContent]
 * @property {any} [intent]
 * @property {any} [visualSpec]
 * @property {any} [cinematicPrimitives]
 */
/**
 * @typedef {object} NodeContext
 * @property {any} THREE
 * @property {any} textureLoader
 * @property {any} glbLoader
 * @property {any} videoLoader
 * @property {any} fontAtlas
 * @property {any} primitives
 * @property {function} emit
 * @property {string} [tier]
 */

export default function createNode(config, ctx) {
    const { Group: ThreeGroup, Mesh: ThreeMesh, PlaneGeometry, Color: ThreeColor, DoubleSide } = ctx.THREE;

    // Helper to fetch colours from visual spec with fallbacks
    const colors = (config.visualSpec && config.visualSpec.colors) || {
        background: '#0b0b10',
        surface: '#16161d',
        ink: '#16161d',
        paper: '#e8ecf2',
        accent: '#ff2a38',
        gradientStops: [{ at: 0, hex: '#ff4450' }, { at: 1, hex: '#c1121f' }]
    };

    // Root group (position/rotation/scale are applied by the adapter)
    const root = new ThreeGroup();

    // ---------- Card Background ----------
    const cardWidth = 2.4;
    const cardHeight = 3.2;
    const halfW = cardWidth / 2;
    const halfH = cardHeight / 2;
    const borderThickness = 0.006;

    // Border lines (four thin planes)
    const lineGeometry = new PlaneGeometry(cardWidth, borderThickness);
    const lineMaterial = new MeshBasicNodeMaterial({ color: new ThreeColor('#2a2a33'), transparent: false, side: DoubleSide });
    // top border
    const borderTop = new ThreeMesh(lineGeometry, lineMaterial);
    borderTop.position.set(0, halfH, 0.001);
    root.add(borderTop);
    // bottom border
    const borderBottom = borderTop.clone();
    borderBottom.position.set(0, -halfH, 0.001);
    root.add(borderBottom);
    // left border (rotate)
    const vertGeom = new PlaneGeometry(borderThickness, cardHeight);
    const borderLeft = new ThreeMesh(vertGeom, lineMaterial);
    borderLeft.position.set(-halfW, 0, 0.001);
    root.add(borderLeft);
    // right border
    const borderRight = borderLeft.clone();
    borderRight.position.set(halfW, 0, 0.001);
    root.add(borderRight);

    // Main surface plane
    const surfaceGeom = new PlaneGeometry(cardWidth, cardHeight);
    const surfaceMat = new MeshStandardNodeMaterial({
        color: new ThreeColor(colors.surface),
        metalness: 0,
        roughness: 1,
        side: DoubleSide
    });
    const surfaceMesh = new ThreeMesh(surfaceGeom, surfaceMat);
    root.add(surfaceMesh);

    // ---------- Header Strip ----------
    const headerHeight = 0.08;
    const headerGeom = new PlaneGeometry(cardWidth, headerHeight);
    const headerMat = new MeshStandardNodeMaterial({
        color: new ThreeColor('#222'), // placeholder base colour
        metalness: 0.5,
        roughness: 0.55,
        clearcoat: 0.2,
        clearcoatRoughness: 0.1,
        side: DoubleSide
    });
    const headerMesh = new ThreeMesh(headerGeom, headerMat);
    headerMesh.position.set(0, halfH - headerHeight / 2, 0.002);
    root.add(headerMesh);

    // ---------- Text Items ----------
    const items = config.textContent ??
        (config.intent && config.intent.visualSpec && config.intent.visualSpec.textContent) ??
        [];

    const textObjects = [];

    // Layout helpers
    const baseY = halfH - headerHeight - 0.15; // start below header strip
    let cursorY = baseY;

    // Tier name
    const tierItem = items.find(i => i.role === 'tier-name' || i.type === 'tier-name');
    if (tierItem) {
        const txt = ctx.fontAtlas.createText(tierItem.text, {
            fontSize: tierItem.typography?.fontSize ?? 20,
            color: colors.paper,
            align: 'center',
            letterSpacingPx: tierItem.typography?.letterSpacing ?? 0
        });
        txt.position.set(0, cursorY, 0.003);
        root.add(txt);
        textObjects.push(txt);
        cursorY -= 0.3; // space after tier name
    }

    // Price figure
    const priceItem = items.find(i => i.role === 'price' || i.type === 'price');
    if (priceItem) {
        const txt = ctx.fontAtlas.createText(priceItem.text, {
            fontSize: priceItem.typography?.fontSize ?? 62,
            color: colors.paper,
            align: 'center',
            letterSpacingPx: priceItem.typography?.letterSpacing ?? 0
        });
        txt.position.set(0, cursorY, 0.003);
        root.add(txt);
        textObjects.push(txt);
        cursorY -= 0.2; // small gap before caption
    }

    // Caption
    const captionItem = items.find(i => i.role === 'caption' || i.type === 'caption');
    if (captionItem) {
        const txt = ctx.fontAtlas.createText(captionItem.text, {
            fontSize: captionItem.typography?.fontSize ?? 9,
            color: colors.paper,
            align: 'center',
            letterSpacingPx: captionItem.typography?.letterSpacing ?? 0
        });
        txt.position.set(0, cursorY, 0.003);
        root.add(txt);
        textObjects.push(txt);
        cursorY -= 0.5; // 0.5-unit gap before features
    }

    // Feature rows
    const featureItems = items.filter(i => i.role === 'feature' || i.type === 'feature');
    const rowHeight = 0.375;
    const separatorHeight = 0.006;
    const featureObjects = [];

    featureItems.forEach((feat, idx) => {
        const yCenter = cursorY - rowHeight / 2 - idx * (rowHeight + separatorHeight);
        const txt = ctx.fontAtlas.createText(feat.text, {
            fontSize: feat.typography?.fontSize ?? 13,
            color: colors.paper,
            align: 'center',
            letterSpacingPx: feat.typography?.letterSpacing ?? 0
        });
        // start offset for animation
        txt.position.set(0, yCenter + 0.2, 0.003);
        // ensure material is transparent for fade
        if (txt.children && txt.children[0] && txt.children[0].material) {
            txt.children[0].material.transparent = true;
            txt.children[0].material.opacity = 0;
        }
        root.add(txt);
        textObjects.push(txt);
        featureObjects.push({ mesh: txt, targetY: yCenter });
        // separator line (except after last)
        if (idx < featureItems.length - 1) {
            const sepGeom = new PlaneGeometry(cardWidth, separatorHeight);
            const sepMat = new MeshBasicNodeMaterial({ color: new ThreeColor('#23232b'), side: DoubleSide });
            const sep = new ThreeMesh(sepGeom, sepMat);
            sep.position.set(0, yCenter - rowHeight / 2 - separatorHeight / 2, 0.003);
            root.add(sep);
        }
    });
    cursorY -= featureItems.length * (rowHeight + separatorHeight);

    // ---------- CTA Row ----------
    const ctaItem = items.find(i => i.role === 'cta-label' || i.type === 'cta-label');
    if (ctaItem) {
        const ctaWidth = 1.4;
        const ctaHeight = 0.36;
        const gradTop = color(colors.gradientStops[0].hex);
        const gradBot = color(colors.gradientStops[1].hex);
        const gradientNode = mix(gradTop, gradBot, uv().y);
        const ctaMat = new MeshStandardNodeMaterial({
            color: gradientNode,
            emissive: new ThreeColor(colors.accent),
            emissiveIntensity: 1.5,
            metalness: 0.3,
            roughness: 0.6,
            side: DoubleSide
        });
        const ctaGeom = new PlaneGeometry(ctaWidth, ctaHeight);
        const ctaMesh = new ThreeMesh(ctaGeom, ctaMat);
        const ctaY = -halfH + 0.5 + ctaHeight / 2;
        ctaMesh.position.set(0, ctaY, 0.004);
        root.add(ctaMesh);

        const txt = ctx.fontAtlas.createText(ctaItem.text, {
            fontSize: ctaItem.typography?.fontSize ?? 13,
            color: colors.paper,
            align: 'center',
            letterSpacingPx: ctaItem.typography?.letterSpacing ?? 0
        });
        txt.position.set(0, ctaY, 0.005);
        root.add(txt);
        textObjects.push(txt);
    }

    // ---------- Animations ----------
    const masterTimeline = gsap.timeline();
    // weighted-settle scale animation
    masterTimeline.fromTo(
        root.scale,
        { x: 1.04, y: 1.04, z: 1.04 },
        {
            x: 1,
            y: 1,
            z: 1,
            duration: 0.9,
            ease: 'cubic-bezier(0.165,0.84,0.44,1)'
        },
        0
    );

    // feature rows stagger fade-up
    featureObjects.forEach((obj, i) => {
        const delay = 0.5 + i * 0.08;
        masterTimeline.to(
            obj.mesh.position,
            { y: obj.targetY, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
            delay
        );
        // opacity animation (assumes first child mesh has material)
        const material = obj.mesh.children?.[0]?.material;
        if (material) {
            masterTimeline.to(
                material,
                { opacity: 1, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
                delay
            );
        }
    });

    // ---------- Cleanup ----------
    root.userData.cleanup = () => {
        masterTimeline.kill();
        // dispose materials & geometries
        surfaceGeom.dispose();
        surfaceMat.dispose();
        headerGeom.dispose();
        headerMat.dispose();
        lineGeometry.dispose();
        vertGeom.dispose();
        lineMaterial.dispose();
        lineMaterial.dispose();
        // CTA
        // (guard against undefined)
        // Dispose any dynamically created geometries/materials
        // Dispose text meshes if they expose dispose (skip if not)
        textObjects.forEach(obj => {
            if (obj.traverse) {
                obj.traverse(child => {
                    if (child.geometry) child.geometry.dispose?.();
                    if (child.material) child.material.dispose?.();
                });
            }
        });
    };

    // No primitive registrations required (none specified)
    root.userData.handlers = {};

    return root;
}
